exports.schoolOutside = { x:lobby.x, z:doors + 1, yaw:Math.PI, zone:'school1', label:'Школа № 1430' };
exports.schoolWalk = { x1:lobby.x, x2:lobby.x, z1:doors, z2:24.6, width:4.6, name:'Дорожка к школе' };
